30	  #[allow(clippy::too_many_arguments)]
31	  pub fn new(mut blueprint: Blueprint, h_client: Arc<Http>, h2_client: Arc<Http>, env: Arc<Env>) -> Self {
32	    let mut http_data_loaders = vec![];
33	    let mut gql_data_loaders = vec![];
34	    let mut grpc_data_loaders = vec![];
35	
36	    for def in blueprint.definitions.iter_mut() {
37	      if let Definition::ObjectTypeDefinition(def) = def {
38	        for field in &mut def.fields {
39	          if let Some(Expression::IO(expr)) = &mut field.resolver {
40	            match expr {
41	              IO::Http { req_template, group_by, .. } => {
42	                let data_loader = HttpDataLoader::new(
43	                  h_client.clone(),
44	                  group_by.clone(),
45	                  matches!(&field.of_type, ListType { .. }),
46	                )
47	                .to_data_loader(blueprint.upstream.batch.clone().unwrap_or_default());
48	
49	                field.resolver = Some(Expression::IO(IO::Http {
50	                  req_template: req_template.clone(),
51	                  group_by: group_by.clone(),
52	                  dl_id: Some(DataLoaderId(http_data_loaders.len())),
53	                }));
54	
55	                http_data_loaders.push(data_loader);
56	              }
57	
58	              IO::GraphQLEndpoint { req_template, field_name, batch, .. } => {
59	                let graphql_data_loader = GraphqlDataLoader::new(h_client.clone(), *batch)
60	                  .to_data_loader(blueprint.upstream.batch.clone().unwrap_or_default());
61	
62	                field.resolver = Some(Expression::IO(IO::GraphQLEndpoint {
63	                  req_template: req_template.clone(),
64	                  field_name: field_name.clone(),
65	                  batch: *batch,
66	                  dl_id: Some(DataLoaderId(gql_data_loaders.len())),
67	                }));
68	
69	                gql_data_loaders.push(graphql_data_loader);
70	              }
71	
72	              IO::Grpc { req_template, group_by, .. } => {
73	                let data_loader = GrpcDataLoader {
74	                  client: h2_client.clone(),
75	                  operation: req_template.operation.clone(),
76	                  group_by: group_by.clone(),
77	                };
78	                let data_loader = data_loader.to_data_loader(blueprint.upstream.batch.clone().unwrap_or_default());
79	
80	                field.resolver = Some(Expression::IO(IO::Grpc {
81	                  req_template: req_template.clone(),
82	                  group_by: group_by.clone(),
83	                  dl_id: Some(DataLoaderId(grpc_data_loaders.len())),
84	                }));
85	
86	                grpc_data_loaders.push(data_loader);
87	              }
88	              _ => {}
89	            }
90	          }
91	        }
92	      }
93	    }
94	
95	    let schema = blueprint.to_schema();
96	
97	    AppContext {
98	      schema,
99	      universal_http_client: h_client,
100	      http2_only_client: h2_client,
101	      blueprint,
102	      http_data_loaders: Arc::new(http_data_loaders),
103	      gql_data_loaders: Arc::new(gql_data_loaders),
104	      cache: ChronoCache::new(),
105	      grpc_data_loaders: Arc::new(grpc_data_loaders),
106	      env_vars: env,
107	    }
108	  }
109	
110	  pub async fn execute(&self, request: impl Into<DynamicRequest>) -> Response {
111	    self.schema.execute(request).await
112	  }
113	}
