54	  pub fn set_min_max_age(&self, max_age: i32) {
55	    let min_max_age_lock = self.get_min_max_age();
56	    match min_max_age_lock {
57	      Some(min_max_age) if max_age < min_max_age => {
58	        self.set_min_max_age_conc(max_age);
59	      }
60	      None => {
61	        self.set_min_max_age_conc(max_age);
62	      }
63	      _ => {}
64	    }
65	  }
