73	  pub fn set_cache_control(&self, cache_policy: CacheControl) {
74	    if let Some(max_age) = cache_policy.max_age {
75	      self.set_min_max_age(max_age.as_secs() as i32);
76	    }
77	    self.set_cache_visibility(&cache_policy.cachability);
78	    if Some(Cachability::NoCache) == cache_policy.cachability {
79	      self.set_min_max_age(-1);
